#!/usr/bin/env python3
# libxmq - Copyright (C) 2026 Fredrik Öhrström (spdx: MIT)
#
# Generate src/main/c/parts/xml_html.c from the libxml2 sources in 3rdparty/libxml2:
# the html element table, the start close table, the end priorities, the elements
# allowing pcdata, and the html5 entity table (codegen/html5ent.inc, copied verbatim).
# The tables are copied from libxml2, the generated file carries the libxml2 notice.
#
# Usage: scripts/generate_xml_html_tables.py [libxml2_dir] [output_file]

import os
import re
import sys

root = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
libxml2 = sys.argv[1] if len(sys.argv) > 1 else os.path.join(root, '3rdparty', 'libxml2')
out_file = sys.argv[2] if len(sys.argv) > 2 else os.path.join(root, 'src', 'main', 'c', 'parts', 'xml_html.c')

src = open(os.path.join(libxml2, 'HTMLparser.c'), encoding='utf-8').read()
ent = open(os.path.join(libxml2, 'codegen', 'html5ent.inc'), encoding='utf-8').read()
copyright = open(os.path.join(libxml2, 'Copyright'), encoding='utf-8').read()
notice = copyright[copyright.index(' Copyright (C) 1998-2012'):].rstrip('\n')
version = re.search(r'LIBXML_DOTTED_VERSION "([^"]+)"',
                    open(os.path.join(libxml2, 'include', 'libxml', 'xmlversion.h'), encoding='utf-8').read()).group(1)

modes = {'0': '0', 'DATA_RCDATA': '1', 'DATA_RAWTEXT': '2', 'DATA_PLAINTEXT': '3', 'DATA_SCRIPT': '4'}

def block(start_marker):
    a = src.index(start_marker)
    a = src.index('{', a) + 1
    b = src.index('\n};', a)
    return src[a:b]

# Element table entries: { "name", startTag, endTag, saveEndTag, empty, depr, dtd, isinline, "desc", 5 x NULL, dataMode }
elements = []
for m in re.finditer(r'\{\s*"([a-z0-9]+)",\s*(\d+),\s*(\d+),\s*(\d+),\s*(\d+),\s*(\d+),\s*(\d+),\s*(\d+),\s*"[^"]*"\s*,'
                     r'\s*NULL,\s*NULL,\s*NULL,\s*NULL,\s*NULL,\s*([A-Z_0-9]+)\s*\}', block('html40ElementTable[] = {')):
    name, start_tag, end_tag, save_end, empty, depr, dtd, isinline, mode = m.groups()
    elements.append((name, end_tag, empty, isinline, modes[mode]))
# Every entry in the table must have been matched.
expected = len(re.findall(r'^\{ *"[a-z0-9]+",', block('html40ElementTable[] = {'), re.M))
assert len(elements) == expected, 'matched %d of %d elements' % (len(elements), expected)
assert elements == sorted(elements, key=lambda e: e[0]), 'element table must be sorted'

start_close = re.findall(r'\{\s*"([a-z0-9]+)",\s*"([a-z0-9]+)"\s*\}', block('htmlStartClose[] = {'))
assert len(start_close) > 200, 'start close table not found'

priorities = re.findall(r'\{\s*"([a-z]+)",\s*(\d+)\s*\}', block('htmlEndPriority[] = {'))
default_priority = re.search(r'\{\s*NULL,\s*(\d+)\s*\}', block('htmlEndPriority[] = {')).group(1)

a = src.index('allowPCData[] = {')
allow_pcdata = re.findall(r'"([a-z0-9]+)"', src[a:src.index('};', a)])

o = []
o.append('''/* libxmq - Copyright (C) 2026 Fredrik Öhrström (spdx: MIT)

Permission is hereby granted, free of charge, to any person obtaining
a copy of this software and associated documentation files (the
"Software"), to deal in the Software without restriction, including
without limitation the rights to use, copy, modify, merge, publish,
distribute, sublicense, and/or sell copies of the Software, and to
permit persons to whom the Software is furnished to do so, subject to
the following conditions:

The above copyright notice and this permission notice shall be
included in all copies or substantial portions of the Software.

THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND,
EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF
MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND
NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE
LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION
OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION
WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.

*/

/* Generated by scripts/generate_xml_html_tables.py from libxml2 ''' + version + ''' (HTMLparser.c,
   HTMLtree.c and codegen/html5ent.inc). Do not edit, regenerate instead.
   The tables are copied from libxml2, which is covered by the following notice
   (from libxml2/Copyright):

''' + notice + '''
*/

#ifndef BUILDING_DIST_XMQ

#include"xml_html.h"

#include<stdlib.h>
#include<string.h>

#endif

#ifdef XML_HTML_MODULE

static const XmlHtmlElementDesc xml_html_elements[] = {
''')
for name, end_tag, empty, isinline, mode in elements:
    o.append('    { "%s", %s, %s, %s, %s },\n' % (name, end_tag, empty, isinline, mode))
o.append('''};

typedef struct
{
    const char *old_tag;
    const char *new_tag;
} XmlHtmlStartClose;

// Sorted by (old_tag, new_tag): a start tag new_tag implicitly closes an open old_tag.
static const XmlHtmlStartClose xml_html_start_close[] = {
''')
for old, new in start_close:
    o.append('    { "%s", "%s" },\n' % (old, new))
o.append('''};

typedef struct
{
    const char *name;
    int priority;
} XmlHtmlPriority;

static const XmlHtmlPriority xml_html_end_priorities[] = {
''')
for name, prio in priorities:
    o.append('    { "%s", %s },\n' % (name, prio))
o.append('''};

#define XML_HTML_DEFAULT_PRIORITY ''' + default_priority + '''

static const char *const xml_html_allow_pcdata[] = {
''')
for i in range(0, len(allow_pcdata), 8):
    o.append('    ' + ' '.join('"%s",' % n for n in allow_pcdata[i:i+8]) + '\n')
o.append('''};

// The html5 named character references, copied verbatim from libxml2 codegen/html5ent.inc.
''')
o.append(ent.rstrip('\n') + '\n')
o.append('''
static int xml_html_compare_element(const void *key, const void *member)
{
    const char *tag = (const char*)key;
    const XmlHtmlElementDesc *desc = (const XmlHtmlElementDesc*)member;
    // Like libxml2 htmlCompareTags (xmlStrcasecmp), the table names are lowercase.
    const unsigned char *a = (const unsigned char*)tag;
    const unsigned char *b = (const unsigned char*)desc->name;
    while (*a && *b)
    {
        int ca = (*a >= 'A' && *a <= 'Z') ? *a + 32 : *a;
        int cb = *b;
        if (ca != cb) return ca - cb;
        a++;
        b++;
    }
    return (int)*a - (int)*b;
}

const XmlHtmlElementDesc *xml_html_element(const char *name)
{
    if (!name) return NULL;
    return (const XmlHtmlElementDesc*)bsearch(name, xml_html_elements,
                                                sizeof(xml_html_elements) / sizeof(xml_html_elements[0]),
                                                sizeof(xml_html_elements[0]), xml_html_compare_element);
}

static int xml_html_compare_start_close(const void *vkey, const void *member)
{
    const XmlHtmlStartClose *key = (const XmlHtmlStartClose*)vkey;
    const XmlHtmlStartClose *entry = (const XmlHtmlStartClose*)member;
    int r = strcmp(key->old_tag, entry->old_tag);
    if (r == 0) r = strcmp(key->new_tag, entry->new_tag);
    return r;
}

bool xml_html_start_closes(const char *new_tag, const char *old_tag)
{
    XmlHtmlStartClose key = { old_tag, new_tag };
    return bsearch(&key, xml_html_start_close,
                   sizeof(xml_html_start_close) / sizeof(xml_html_start_close[0]),
                   sizeof(xml_html_start_close[0]), xml_html_compare_start_close) != NULL;
}

int xml_html_end_priority(const char *name)
{
    for (size_t i = 0; i < sizeof(xml_html_end_priorities) / sizeof(xml_html_end_priorities[0]); ++i)
    {
        if (!strcmp(xml_html_end_priorities[i].name, name)) return xml_html_end_priorities[i].priority;
    }
    return XML_HTML_DEFAULT_PRIORITY;
}

bool xml_html_allows_pcdata(const char *name)
{
    if (!name) return false;
    for (size_t i = 0; i < sizeof(xml_html_allow_pcdata) / sizeof(xml_html_allow_pcdata[0]); ++i)
    {
        if (!strcmp(xml_html_allow_pcdata[i], name)) return true;
    }
    return false;
}

static int xml_html_ascii_casecmp(const char *a, const char *b)
{
    while (*a && *b)
    {
        int ca = (*a >= 'A' && *a <= 'Z') ? *a + 32 : *a;
        int cb = (*b >= 'A' && *b <= 'Z') ? *b + 32 : *b;
        if (ca != cb) return ca - cb;
        a++;
        b++;
    }
    return (unsigned char)*a - (unsigned char)*b;
}

bool xml_html_is_boolean_attr(const char *name)
{
    // Port of libxml2 htmlIsBooleanAttr (HTMLtree.c): the html 4 attributes written in minimized form.
    static const char *const names[] = {
        "checked", "compact", "declare", "defer", "disabled", "ismap", "multiple", "nohref",
        "noresize", "noshade", "nowrap", "readonly", "selected"
    };
    if (!name) return false;
    for (size_t i = 0; i < sizeof(names) / sizeof(names[0]); ++i)
    {
        if (!xml_html_ascii_casecmp(name, names[i])) return true;
    }
    return false;
}

#define ENT_F_SEMICOLON 0x80u
#define ENT_F_SUBTABLE  0x40u
#define ENT_F_ALL       0xC0u

static bool xml_html_is_ascii_letter(int c)
{
    return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z');
}

static bool xml_html_is_alnum(int c)
{
    return xml_html_is_ascii_letter(c) || (c >= '0' && c <= '9');
}

const unsigned char *xml_html_find_entity_prefix(const unsigned char *string, size_t slen, bool is_attr,
                                                 size_t *nlen, size_t *rlen)
{
    // Port of libxml2 htmlFindEntityPrefix.
    const unsigned char *match = NULL;
    unsigned left, right;
    int first = string[0];
    size_t match_len = 0;
    size_t soff = 1;

    if (slen < 2) return NULL;
    if (!xml_html_is_ascii_letter(first)) return NULL;

    // Look up range by first character.
    first &= 63;
    left = htmlEntAlpha[first*3] | htmlEntAlpha[first*3+1] << 8;
    right = left + htmlEntAlpha[first*3+2];

    // Binary search.
    while (left < right)
    {
        const unsigned char *bytes;
        unsigned mid;
        size_t len;
        int cmp;

        mid = left + (right - left) / 2;
        bytes = htmlEntStrings + htmlEntValues[mid];
        len = bytes[0] & ~ENT_F_ALL;

        cmp = string[soff] - bytes[1];

        if (cmp == 0)
        {
            if (slen < len)
            {
                cmp = strncmp((const char*)string + soff + 1, (const char*)bytes + 2, slen - 1);
                // Prefix can never match.
                if (cmp == 0) break;
            }
            else
            {
                cmp = strncmp((const char*)string + soff + 1, (const char*)bytes + 2, len - 1);
            }
        }

        if (cmp < 0)
        {
            right = mid;
        }
        else if (cmp > 0)
        {
            left = mid + 1;
        }
        else
        {
            int term = soff + len < slen ? string[soff + len] : 0;
            bool is_alnum = xml_html_is_alnum(term);
            bool is_term = (term == ';') ||
                           ((bytes[0] & ENT_F_SEMICOLON) && ((!is_attr) || ((!is_alnum) && (term != '='))));

            if (is_term)
            {
                match = bytes + len + 1;
                match_len = soff + len;
                if (term == ';') match_len += 1;
            }

            if (bytes[0] & ENT_F_SUBTABLE)
            {
                if (is_term) match += 2;

                if (is_alnum && (soff + len < slen))
                {
                    left = mid + bytes[len + 1];
                    right = left + bytes[len + 2];
                    soff += len;
                    continue;
                }
            }

            break;
        }
    }

    if (match == NULL) return NULL;

    *nlen = match_len;
    *rlen = match[0];
    return match + 1;
}

#endif // XML_HTML_MODULE
''')
open(out_file, 'w', encoding='utf-8').write(''.join(o))
print('wrote %s: %d elements, %d start close entries, %d priorities' % (out_file, len(elements), len(start_close), len(priorities)))
